functions.upDataWeapon:
{
   var _loc4_;
   var _loc12_;
   var _loc3_;
   var _loc5_;
   var _loc11_;
   var _loc13_;
   var _loc14_;
   var _loc15_;
   var _loc6_;
   var _loc7_;
   var _loc10_;
   var _loc8_;
   var _loc9_;
   if(target.type == "头盔" || target.type == "衣服" || target.type == "武器" || target.type == "鞋" || target.type == "幸运符" || target.type == "戒指")
   {
      if(target.type == "幸运符")
      {
         _loc4_ = target.luckLevels + target.isFirstLove + 1;
         target.moreExp = _loc4_ * 10 * (target.grade >= 0);
         target.moreLife = _loc4_ * (target.grade >= 1);
         target.moreMp = _loc4_ * (target.grade >= 1);
         target.moreDefense = _loc4_ * (target.grade >= 2);
         target.moreAttack = _loc4_ * (target.grade >= 3);
         target.resumeLife = _loc4_ * (target.grade >= 4);
         return true;
      }
      if(target.type == "戒指")
      {
         _loc12_ = 1;
         if(target.name == "新手戒指")
         {
            _loc12_ = 5;
         }
         target[target.mainType1] = ringMainValue[target.mainType1][target.grade] / _loc12_;
         target[target.mainType2] = ringMainValue[target.mainType2][target.grade] / _loc12_;
         target.salePrice = 10;
         return true;
      }
      if(undefined == target.levels)
      {
         target.levels = 1;
      }
      if(undefined == target.grade)
      {
         target.grade = 0;
      }
      if(undefined == target.mhdj)
      {
         target.mhdj = 0;
      }
      if(undefined == target.minAttack)
      {
         target.minAttack = 0;
      }
      if(undefined == target.maxAttack)
      {
         target.maxAttack = 0;
      }
      if(undefined == target.mMinAttack)
      {
         target.mMinAttack = 0;
      }
      if(undefined == target.mMaxAttack)
      {
         target.mMaxAttack = 0;
      }
      if(undefined == target.defense)
      {
         target.defense = 0;
      }
      if(undefined == target.mDefense)
      {
         target.mDefense = 0;
      }
      if(undefined == target.element)
      {
         target.element = 0;
      }
      if(undefined == target.wind)
      {
         target.wind = 0;
      }
      if(undefined == target.fire)
      {
         target.fire = 0;
      }
      if(undefined == target.soil)
      {
         target.soil = 0;
      }
      if(undefined == target.water)
      {
         target.water = 0;
      }
      if(undefined == target.holes)
      {
         target.holes = 0;
      }
      if(undefined == target.hole1)
      {
         target.hole1 = 0;
         target.gem1 = 0;
         target.gem11 = 0;
      }
      if(undefined == target.hole2)
      {
         target.hole2 = 0;
         target.gem2 = 0;
         target.gem12 = 0;
      }
      if(undefined == target.hole3)
      {
         target.hole3 = 0;
         target.gem3 = 0;
         target.gem13 = 0;
      }
      if(undefined == target.additional)
      {
         target.additional = 0;
      }
      if(undefined == target.spirit)
      {
         target.spirit = 0;
         target.spiritVal = 0;
         target.spiritLevels = 0;
         target.spiritExp = 0;
      }
      _loc3_ = new Array(8,16,32,64,128,256,512);
      _loc5_ = target.levels * 1.5 + 5;
      if(target.vocational == "战士")
      {
         _loc11_ = 3 + target.grade * 0.3;
         _loc13_ = 1 + target.grade * 0.1;
         _loc14_ = 0.4 + target.grade * 0.05;
         _loc15_ = 0.2 + target.grade * 0.02;
         _loc6_ = 0.1;
      }
      else
      {
         _loc11_ = 3.6 + target.grade * 0.36;
         _loc13_ = 1.2 + target.grade * 0.12;
         _loc14_ = 0.3 + target.grade * 0.03;
         _loc15_ = 0.1 + target.grade * 0.02;
         _loc6_ = 0.4;
      }
      if(target.type == "武器")
      {
         target.name = _global[target.vocational + "weaponName"][Math.floor((target.levels > 120 ? 120 : target.levels) / 15)];
         target.minAttack = Math.round(_loc5_ * _loc11_ * _loc6_);
         target.maxAttack = Math.round(_loc5_ * _loc11_ * (1 - _loc6_));
         target.mMinAttack = Math.ceil(target.mhdj * target.minAttack / 20);
         target.mMaxAttack = Math.ceil(target.mhdj * target.maxAttack / 20);
      }
      else if(target.type == "鞋")
      {
         target.name = _global[target.vocational + "shoesName"][Math.floor((target.levels > 120 ? 120 : target.levels) / 15)];
         target.minAttack = Math.round(_loc5_ * _loc13_ * _loc6_);
         target.maxAttack = Math.round(_loc5_ * _loc13_ * (1 - _loc6_));
         target.mMinAttack = Math.ceil(target.mhdj * target.minAttack / 20);
         target.mMaxAttack = Math.ceil(target.mhdj * target.maxAttack / 20);
      }
      else if(target.type == "衣服")
      {
         target.name = _global[target.vocational + "clotheName"][Math.floor((target.levels > 120 ? 120 : target.levels) / 15)];
         target.defense = Math.round(_loc5_ * _loc14_);
         target.mDefense = Math.ceil(target.mhdj * target.defense / 20);
      }
      else if(target.type == "头盔")
      {
         target.name = _global[target.vocational + "helmetName"][Math.floor((target.levels > 120 ? 120 : target.levels) / 15)];
         target.defense = Math.round(_loc5_ * _loc15_);
         target.mDefense = Math.ceil(target.mhdj * target.defense / 20);
      }
      _loc7_ = 0;
      _loc10_ = 0;
      _loc8_ = 0;
      _loc9_ = 0;
      switch(target.element)
      {
         case undefined:
         case 0:
            break;
         case 1:
            _loc7_ = _loc3_[target.grade];
            break;
         case 2:
            _loc10_ = _loc3_[target.grade];
            break;
         case 3:
            _loc8_ = _loc3_[target.grade];
            break;
         case 4:
            _loc9_ = _loc3_[target.grade];
            break;
         case 5:
            _loc7_ = _loc3_[target.grade] / 2;
            _loc10_ = _loc3_[target.grade] / 2;
            _loc9_ = _loc3_[target.grade] / 2;
            _loc8_ = _loc3_[target.grade] / 2;
      }
      target.wind = target.wind <= _loc7_ ? _loc7_ : target.wind;
      target.fire = target.fire <= _loc10_ ? _loc10_ : target.fire;
      target.soil = target.soil <= _loc9_ ? _loc9_ : target.soil;
      target.water = target.water <= _loc8_ ? _loc8_ : target.water;
      target.salePrice = 0;
      switch(target.grade)
      {
         case 1:
            target.salePrice += 80;
            break;
         case 2:
            target.salePrice += 240;
            break;
         case 3:
            target.salePrice += 560;
            break;
         case 4:
            target.salePrice += 1360;
      }
      switch(target.element)
      {
         case 1:
         case 2:
         case 3:
         case 4:
            target.salePrice += 500;
            break;
         case 5:
            target.salePrice += 2000;
      }
      switch(target.holes)
      {
         case 1:
            target.salePrice += 400;
            break;
         case 2:
            target.salePrice += 2400;
            break;
         case 3:
            target.salePrice += 10400;
      }
      target.salePrice += target.levels * 4;
      target.salePrice += !isNaN(target.mhdj) ? target.mhdj * 10 : 0;
      return true;
   }
   if(target.type == "凤翼铃铛" || target.type == "翡翠铃铛" || target.type == "庇护铃铛")
   {
      i = 1;
      while(i <= 3)
      {
         if(target.grade - i < -1)
         {
            break;
         }
         switch(target["attributeType" + i])
         {
            case 1:
               target["attributeVal" + i] = (target.grade + 2 - i) * 5;
               break;
            case 2:
               target["attributeVal" + i] = (target.grade + 2 - i) * 3;
               break;
            case 3:
               target["attributeVal" + i] = (target.grade + 2 - i) * 4;
         }
         i++;
      }
      target.salePrice = (target.grade + 1) * 100;
      return true;
   }
   return false;
}

functions.flashInfo:
{
   if(this.item.type == "幸运符")
   {
      if(this.stone.type == "空格")
      {
         this.info.text = "幸运符能用灵魂晶石或灵魂王提高品质，用紫水晶提高幸运等级。";
         return false;
      }
      switch(this.stone.name)
      {
         case "灵魂晶石":
            if(this.item.grade < 4)
            {
               this.info.text = "可以打造   需要宝石数量：" + this.gradeSuccess[this.item.grade] + "\n" + "成功后品质提升到" + _global.gradeName[this.item.grade + 1] + "\n" + "失败则品质不变";
               this.info.text += "\r注意：升级品质后幸运等级可能降低。";
            }
            else
            {
               this.info.text = "装备品质已经最高了";
            }
            break;
         case "灵魂王":
            if(this.item.grade < 4)
            {
               this.info.text = "可以打造\r需要宝石数量：1\r成功后品质提升到" + _global.gradeName[this.item.grade + 1];
            }
            else
            {
               this.info.text = "装备品质已经最高了";
            }
            break;
         case "紫水晶":
            if(this.item.luckLevels < 3)
            {
               this.info.text = "可以打造\r需要宝石数量：1\r成功后幸运等级为" + (this.item.luckLevels + 1) + "级";
            }
            else if(this.item.luckLevels < 6)
            {
               this.info.text = "可以打造\r需要宝石数量：3\r成功后幸运等级为" + (this.item.luckLevels + 1) + "级";
            }
            else if(this.item.luckLevels < 12)
            {
               this.info.text = "可以打造\r需要宝石数量：5\r成功后成功后幸运等级为" + (this.item.luckLevels + 1) + "级";
            }
            else
            {
               this.info.text = "不可以打造\r幸运等级已经到最高级了";
            }
            break;
         default:
            this.info.text = "不可打造\r幸运符只能用灵魂晶石或灵魂王提高品质，用紫水晶提高幸运等级。";
      }
      return false;
   }
   if(this.item.type != "戒指")
   {
      if(this.item.type != "空格")
      {
         if(this.stone.type == "空格")
         {
            this.info.text = "";
         }
         switch(this.stone.name)
         {
            case "中级攻击宝石":
            case "高级攻击宝石":
               if((this.item.type == "武器" || this.item.type == "鞋") && (this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0))
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r攻击力增加" + this.stone.val1 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "中级减伤害宝石":
            case "高级减伤害宝石":
               if((this.item.type == "衣服" || this.item.type == "头盔") && (this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0))
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r受到伤害减少" + this.stone.val1 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "中级经验宝石":
            case "高级经验宝石":
               if(this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0)
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r战斗获得经验增加" + this.stone.val1 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "中级战斗力宝石":
            case "高级战斗力宝石":
               if(this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0)
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r战斗力增加" + this.stone.val1 + "点";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "战斗攻击圣石":
               if((this.item.type == "武器" || this.item.type == "鞋") && (this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0))
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r战斗力增加" + this.stone.val1 + "点";
                  this.info.text += "\r攻击力增加" + this.stone.val2 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "战斗减伤害圣石":
               if((this.item.type == "衣服" || this.item.type == "头盔") && (this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0))
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r战斗力增加" + this.stone.val1 + "点";
                  this.info.text += "\r受到伤害减少" + this.stone.val2 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "战斗经验圣石":
               if(this.item.holes > 0 && this.item.hole1 == 0 || this.item.holes > 1 && this.item.hole2 == 0 || this.item.holes > 2 && this.item.hole3 == 0)
               {
                  this.info.text = "可以镶嵌\r镶嵌后效果：\r战斗力增加" + this.stone.val1 + "点";
                  this.info.text += "\r战斗获得经验" + this.stone.val2 + "%";
               }
               else
               {
                  this.info.text = "不能镶嵌";
               }
               break;
            case "灵魂晶石":
               if(this.item.grade < 4)
               {
                  this.info.text = "可以打造\r需要宝石数量：" + this.gradeSuccess[this.item.grade] + "\n" + "成功后品质提升到" + _global.gradeName[this.item.grade + 1] + "\n" + "失败则品质不变";
               }
               else
               {
                  this.info.text = "不可以打造";
               }
               break;
            case "灵魂王":
               if(this.item.grade < 4)
               {
                  this.info.text = "可以打造\r需要宝石数量：1\r成功后品质提升到" + _global.gradeName[this.item.grade + 1];
               }
               else if(this.item.grade == 4)
               {
                  this.info.text = "可以打造\r需要宝石数量：5\r需要消耗20点声望！\r成功后品质提升到" + _global.gradeName[this.item.grade + 1];
               }
               else if(this.item.grade == 5)
               {
                  this.info.text = "可以打造\r需要宝石数量：10\r需要消耗50点声望！\r成功后品质提升到" + _global.gradeName[this.item.grade + 1];
               }
               else
               {
                  this.info.text = "装备品质已经最高了";
               }
               break;
            case "玄铁矿":
               if(this.item.spirit == 0)
               {
                  if(this.item.additional == 0)
                  {
                     this.info.text = "可以打造\r打造后装备会产生一个附加效果。";
                  }
                  else
                  {
                     this.info.text = "可以打造\r打造后装备会产生一个附加效果。\r注意：原来的附加效果将会消失。";
                  }
               }
               else
               {
                  this.info.text = "该装备的附加效果已经激活为战魂了，所以不能再产生附加效果。";
               }
               break;
            case "陨铁矿":
               if(this.item.spirit == 0)
               {
                  switch(this.item.additional)
                  {
                     case 0:
                        this.info.text = "不可以打造\r该装备没有附加效果，无法激活战魂。";
                        break;
                     case 1:
                     case 2:
                        this.info.text = "可以打造\r打造后激活战魂--狂。";
                        break;
                     case 3:
                        this.info.text = "可以打造\r打造后激活战魂--仙。";
                        break;
                     case 4:
                        this.info.text = "可以打造\r打造后激活战魂--灵。";
                  }
               }
               else
               {
                  this.info.text = "不可以打造\r该装备已经有战魂。";
               }
               break;
            case "魔魂晶石":
               if(this.item.mhdj == 0)
               {
                  this.info.text = "可以打造\r需要宝石数量：" + (this.item.mhdj + 1) * 2 + "\n" + "成功后魔魂   +" + (this.item.mhdj + 1);
               }
               else if(this.item.mhdj < 19)
               {
                  this.info.text = "可以打造\r需要宝石数量：" + (this.item.mhdj + 1) * 2 + "\n" + "成功后魔魂   +" + (this.item.mhdj + 1);
               }
               else
               {
                  this.info.text = "不可以打造";
               }
               break;
            case "魔魂之心":
               if(this.item.mhdj < 19)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后魔魂   +" + (this.item.mhdj + 1);
               }
               else if(this.item.grade == 5 && this.item.mhdj < 38)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后魔魂   +" + (this.item.mhdj + 1);
               }
               else if(this.item.grade == 6 && this.item.mhdj < 50)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后魔魂   +" + (this.item.mhdj + 1);
               }
               else
               {
                  this.info.text = "装备魔魂等级已经最高了";
               }
               break;
            case "幻魔晶石":
               if(this.item.levels == 1)
               {
                  this.info.text = "可以打造\r需要宝石数量：1\r成功后升级为15级装备\r失败则等级不变";
               }
               else if(this.item.levels < 120)
               {
                  this.info.text = "可以打造\r需要宝石数量：" + this.item.levels + "" + "\n" + "成功后升级为" + (this.item.levels + 15) + "级装备" + "\n" + "失败则等级不变";
