               }
               else
               {
                  this.info.text = "装备使用等级不能超过人物的最高等级";
               }
               break;
            case "幻魔之心":
               if(this.item.levels == 1)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后升级为15级装备";
               }
               else if(this.item.levels < 120)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后升级为" + (this.item.levels + 15) + "级装备";
               }
               else if(this.item.levels < this._parent.map.role.maxLevels)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后升级为" + (this.item.levels + 1) + "级装备";
               }
               else
               {
                  this.info.text = "装备使用等级不能超过人物的最高等级";
               }
               break;
            case "初级月光宝盒":
               if(this.item.holes == 0)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后装备增加一个可以镶嵌宝石的洞";
               }
               else
               {
                  this.info.text = "不可以打造";
               }
               break;
            case "中级月光宝盒":
               if(this.item.holes == 1)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后装备增加第二个可以镶嵌宝石的洞";
               }
               else
               {
                  this.info.text = "不可以打造";
               }
               break;
            case "高级月光宝盒":
               if(this.item.holes == 2)
               {
                  this.info.text = "可以打造\r成功率100%\r成功后装备增加第三个可以镶嵌宝石的洞";
               }
               else
               {
                  this.info.text = "不可以打造";
               }
               break;
            case "紫水晶":
               this.info.text = "不可以打造\r紫水晶只能于提高幸运符的幸运等级。";
               break;
            case "大元素石":
               if(this.item.grade >= 4)
               {
                  this.info.text = "可以打造\r成功后所有元素攻击加1。";
               }
               else
               {
                  this.info.text = "神品装备才可以打造。";
               }
               break;
            case "小元素石":
               if(this.item.grade >= 4)
               {
